create function moneyspace_private.block_new_auth_users() returns trigger language plpgsql security invoker set search_path='' as $$ begin if current_user not in ('postgres','supabase_admin') then raise exception 'New account registration is disabled' using errcode='42501'; end if; return new; end $$; revoke all on function moneyspace_private.block_new_auth_users() from public,anon,authenticated; create trigger moneyspace_registration_closed before insert on auth.users for each row execute function moneyspace_private.block_new_auth_users();
